 const[expenses,setExpenses]=useState<Expense[]>([]);const[expenseCategory,setExpenseCategory]=useState("Contabilidade");const[expenseCustom,setExpenseCustom]=useState("");const[expenseAmount,setExpenseAmount]=useState("0");const[expenseDate,setExpenseDate]=useState(todayKey());
 const[pricingCategories,setPricingCategories]=useState<PricingCategory[]>([]);const[shippingBands,setShippingBands]=useState<ShippingBand[]>([]);const[itemPricingCategories,setItemPricingCategories]=useState<{item_id:string;category_id:number}[]>([]);const[priceItem,setPriceItem]=useState("");const[priceCategory,setPriceCategory]=useState("");const[priceSale,setPriceSale]=useState("");const[priceBand,setPriceBand]=useState("Leve");const[priceShipOverride,setPriceShipOverride]=useState("");const[priceNewCategory,setPriceNewCategory]=useState("");const[priceNewFee,setPriceNewFee]=useState("18");const[priceTarget,setPriceTarget]=useState("20");const[competitorUrl,setCompetitorUrl]=useState("");const[competitor,setCompetitor]=useState<any>(null);const[competitorLoading,setCompetitorLoading]=useState(false);const[buyCost,setBuyCost]=useState("");const[priceWeight,setPriceWeight]=useState("");const[priceDimensions,setPriceDimensions]=useState("");const[feeOverride,setFeeOverride]=useState("");
 const[loading,setLoading]=useState(false);const[error,setError]=useState("");const[filter,setFilter]=useState("");const[tab,setTab]=useState<"expedicao"|"estoque"|"historico"|"financeiro"|"recebimentos"|"movimentacoes"|"dre"|"alertas"|"promocoes"|"cadastro"|"operacional">("expedicao");const[view,setView]=useState<"produtos"|"pedidos">("produtos");const[dispatchView,setDispatchView]=useState<"hoje"|"futuros"|"enviados">("hoje");const[updated,setUpdated]=useState("");const[selected,setSelected]=useState<string|null>(null);const[edit,setEdit]=useState<{cost:string;lead:string;safety:string;physical:string}|null>(null);const[saving,setSaving]=useState(false);
 useEffect(()=>{if(!supabase)return;supabase.auth.getSession().then(({data})=>setSession(data.session));const{data:{subscription}}=supabase.auth.onAuthStateChange((_event,s)=>setSession(s));return()=>subscription.unsubscribe()},[]);
