 async function mod(module:string,method:"GET"|"POST"="GET",payload?:unknown){if(!supabase)throw Error("Conexão indisponível");const{data:{session:s}}=await supabase.auth.getSession();if(!s)throw Error("Entre novamente na sua conta");const res=await fetch(url+"/functions/v1/pearland-modules-api?module="+encodeURIComponent(module),{method,headers:{Authorization:"Bearer "+s.access_token,...(payload?{"Content-Type":"application/json"}:{})},body:payload?JSON.stringify(payload):undefined});const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(body.error||"Falha ao carregar");return body}
 const[promoData,setPromoData]=useState<{promotions:Promo[];economics:Econ[];actions:any[]}|null>(null);const[promoLoading,setPromoLoading]=useState(false);const[promoDraft,setPromoDraft]=useState<Record<string,{price:string;stock:string;confirm:boolean}>>({});const[promoBusy,setPromoBusy]=useState("");const[promoRefused,setPromoRefused]=useState<Set<string>>(new Set());
