 const promoErr=(e:string)=>({price_above_max:"Preço acima do máximo permitido pela campanha.",price_below_min:"Preço abaixo do mínimo permitido.",invalid_price:"Informe um preço válido.",invalid_stock:"Informe uma quantidade válida.",promotion_not_open_for_acceptance:"Esta promoção não está mais aberta para adesão.",type_not_supported:"Este tipo de promoção ainda precisa ser aceito pelo ML.",ml_rejected:"O Mercado Livre recusou a adesão."} as Record<string,string>)[e]||e;
 async function acceptPromo(p:Promo,price:number|null,stock:string){const key=p.item_id+"|"+p.promotion_id;setPromoBusy(key);setError("");setNotice("");try{const res=await fetch(url+"/functions/v1/pearland-modules-api?module=promotions",{method:"POST",headers:{Authorization:"Bearer "+(await supabase!.auth.getSession()).data.session!.access_token,"Content-Type":"application/json"},body:JSON.stringify({action:"accept",item_id:p.item_id,promotion_id:p.promotion_id,deal_price:price,stock:stock||null})});const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(promoErr(body.error)+(body.message?" ("+body.message+")":""));setNotice("Promoção aceita no Mercado Livre: "+(p.name||promoTypeLabel(p.promotion_type))+(price?" a "+money(price):"")+".");setPromoDraft(d=>({...d,[key]:{...(d[key]||{price:"",stock:""}),confirm:false}}));await loadPromos();}catch(e:any){setError("Promoção não aceita: "+e.message)}finally{setPromoBusy("")}}
 const[cashMonth,setCashMonth]=useState(new Date().toISOString().slice(0,7));
 const[cash,setCash]=useState<{rows:any[];closings:any[];bank_sync:string}|null>(null);
