 async function saveExpense(){setSaving(true);setError("");try{const category=(expenseCategory==="Outros"?expenseCustom:expenseCategory).trim();const normalized=expenseAmount.trim().replace(/\s/g,"").replace(/^R\$\s*/i,"");const amount=Number(normalized.includes(",")?normalized.replace(/\./g,"").replace(",","."):normalized);if(!category||!Number.isFinite(amount)||amount<0||expenseDate<todayKey())throw Error("Informe categoria, valor válido e data de hoje ou futura.");await api("POST",{action:"save_expense",category,effective_date:expenseDate,monthly_amount:amount});await refresh();setNotice("Despesa operacional salva no banco: "+category+" · "+money(amount)+"/mês · vigência "+expenseDate.split("-").reverse().join("/")+".");}catch(e:any){setError("Despesa não gravada: "+(e.message||"erro desconhecido")+". Confira o valor e a data.");}finally{setSaving(false)}}
 const pending=useMemo(()=>orders.filter(active),[orders]);
