 const visible=useMemo(()=>dispatchOrders.filter(o=>[o.buyer_name,o.buyer_nickname,o.order_id,...o.items.map(i=>i.title)].join(" ").toLowerCase().includes(filter.toLowerCase())),[dispatchOrders,filter]);
 const products=useMemo(()=>{const m=new Map<string,{name:string;qty:number;orders:Set<string>;ready:number;ids:Set<string>}>();for(const o of visible)for(const i of o.items){const key=i.item_id||i.title;const v=m.get(key)||{name:i.title,qty:0,orders:new Set<string>(),ready:0,ids:new Set<string>()};v.qty+=i.quantity;v.orders.add(o.order_id);v.ids.add(o.order_id);if(o.print_status!=="not_queued")v.ready+=i.quantity;m.set(key,v)}return[...m.entries()].sort((a,b)=>b[1].qty-a[1].qty)},[visible]);
 const history=useMemo(()=>orders.filter(o=>!active(o)).filter(o=>[o.buyer_name,o.buyer_nickname,o.order_id,...o.items.map(i=>i.title)].join(" ").toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>+new Date(b.date_created)-+new Date(a.date_created)),[orders,filter]);
 const soldToday=orders.filter(o=>o.status==="paid"&&day(o.date_created)===todayKey());
 const salesPeriod=useMemo(()=>{const today=todayKey(),d=new Date(today+"T12:00:00Z"),offset=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-offset);const monday=d.toISOString().slice(0,10),month=today.slice(0,7);const paid=orders.filter(o=>o.status==="paid");return {week:paid.filter(o=>day(o.date_created)>=monday&&day(o.date_created)<=today).length,month:paid.filter(o=>day(o.date_created).slice(0,7)===month).length,all:paid.length};},[orders]);
 const weeklyGross=useMemo(()=>{const today=todayKey(),d=new Date(today+"T12:00:00Z");d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);const monday=d.toISOString().slice(0,10);return orders.filter(o=>o.status==="paid"&&day(o.date_created)>=monday&&day(o.date_created)<=today).reduce((sum,o)=>sum+Number(o.paid_amount||0),0);},[orders]);
 // Resumo por SKU: unidades da lista selecionada (hoje / próximos / enviados) e unidades vendidas hoje.
 const skuSummary=(list:Order[])=>{const m=new Map<string,{id:string;name:string;qty:number}>();for(const o of list)for(const i of o.items){const k=i.item_id||i.title;const v=m.get(k)||{id:i.item_id,name:i.title,qty:0};v.qty+=i.quantity;m.set(k,v)}return [...m.values()].sort((a,b)=>b.qty-a.qty||a.name.localeCompare(b.name))};
 const shortName=(t:string)=>t.split(/\s+/).slice(0,4).join(" ");
