 async function login(e:React.FormEvent){e.preventDefault();setError("");setNotice("");if(!supabase)return;setLoading(true);if(signup){if(email.trim().toLowerCase()!=="veranticomercio@gmail.com"){setError("Cadastro inicial reservado ao administrador.");setLoading(false);return}const{error}=await supabase.auth.signUp({email,password,emailRedirectTo:"https://pearland-erp.veranticomercio.workers.dev"});if(error)setError(error.message);else setNotice("Confira seu e-mail para confirmar o cadastro.")}else{const{error}=await supabase.auth.signInWithPassword({email,password});if(error)setError("Não foi possível entrar. Confira e-mail e senha.")}setLoading(false)}
