 {tab==="expedicao"&&<><div className="dispatch-switch"><button className={dispatchView==="hoje"?"on":""} onClick={()=>setDispatchView("hoje")}>Envios de hoje <b>{readyToday.length}</b></button><button className={dispatchView==="futuros"?"on":""} onClick={()=>setDispatchView("futuros")}>Próximos envios <b>{futureOrders.length}</b></button><button className={dispatchView==="enviados"?"on":""} onClick={()=>setDispatchView("enviados")}>Enviados hoje <b>{sentToday.length}</b></button></div><p className="dispatch-hint">{dispatchView==="hoje"?"Toda etiqueta enviada à impressora é envio do dia. Etiquetas enviadas depois das 15h entram no envio do dia seguinte. Pedido não despachado continua aqui até sair.":dispatchView==="futuros"?"Pedidos pendentes por data de liberação: os de amanhã primeiro; datas posteriores aparecem mais claras. Pedidos já despachados não entram nesta lista.":"Pedidos entregues ao ponto de postagem. Quando o ML não informa a data exata, usamos o dia em que o ERP identificou o despacho."}</p>{(()=>{const rows:[string,ReturnType<typeof skuSummary>][]=[[dispatchView==="hoje"?"Para enviar hoje":dispatchView==="futuros"?"Próximos envios":"Enviados hoje",skuSummary(dispatchOrders)],["Vendidos hoje",skuSummary(soldToday)]];return <section className="sku-strip">{rows.map(([label,list])=><div className="sku-strip-row" key={label}><span className="sku-strip-label">{label}<b>{list.reduce((n,x)=>n+x.qty,0)} un.</b></span><div className="sku-strip-chips">{list.length?list.map(x=>{const thumb=inventoryMap.get(x.id)?.thumbnail;return <button key={x.id||x.name} className="sku-chip" title={x.name+" — clique para filtrar"} onClick={()=>setFilter(filter===x.name?"":x.name)}>{thumb?<img src={thumb} alt="" loading="lazy"/>:<Box size={16}/>}<span>{shortName(x.name)}</span><b>{x.qty}</b></button>}):<small className="muted">Nenhum item</small>}</div></div>)}</section>})()}<div className="subtabs"><button className={view==="produtos"?"on":""} onClick={()=>setView("produtos")}>Separar por produto</button><button className={view==="pedidos"?"on":""} onClick={()=>setView("pedidos")}>Ver por pedido</button></div>{view==="produtos"?<section className="products">{products.map(([id,p])=><div className="product-group" key={id}><div className="product-group-title"><strong>{p.name}</strong><span>{p.qty} unidades · {p.orders.size} pedidos</span></div>{visible.filter(o=>o.items.some(i=>(i.item_id||i.title)===id)).map(o=><div className="buyer-line" key={o.order_id} style={laterDispatch(o)?{opacity:.48}:{}}><div><strong>{o.buyer_name||o.buyer_nickname||"Comprador"}</strong>{o.buyer_name&&o.buyer_nickname&&<small> ({o.buyer_nickname})</small>}<small> · Pedido {o.order_id}</small>{dispatchView==="futuros"&&<small> · Liberação: {releaseLabel(o)}</small>}</div><div><b>{o.items.filter(i=>(i.item_id||i.title)===id).reduce((n,i)=>n+i.quantity,0)} un.</b><small>{printLabel(o.print_status)}</small></div></div>)}</div>)}{!products.length&&<div className="empty">Nenhum pedido nesta seleção</div>}</section>:<section className="orders">{visible.map(o=><article className="order" key={o.order_id} style={laterDispatch(o)?{opacity:.48}:{}}><div className="order-top"><div><strong>{o.buyer_name||o.buyer_nickname||"Comprador não informado"}</strong>{o.buyer_name&&o.buyer_nickname&&<span className="muted"> ({o.buyer_nickname})</span>}</div><time>{date(o.date_created)}</time></div><small>Pedido {o.order_id} · {statusLabel(o)}{dispatchView==="futuros"?" · Liberação: "+releaseLabel(o):""}</small><div className="items">{o.items.map((i,n)=><div key={n}><span>{i.title}</span><b>× {i.quantity}</b></div>)}</div><div className="order-bottom"><span>Nota: <b>{invoiceLabel(o.invoice_status)}</b></span><span>Etiqueta: <b>{printLabel(o.print_status)}</b></span><strong>{money(o.paid_amount)}</strong></div></article>)}{!visible.length&&<div className="empty">Nenhum pedido nesta seleção</div>}</section>}</>}
 {tab==="estoque"&&<section className="stock-grid">{stockRows.filter(i=>i.title.toLowerCase().includes(filter.toLowerCase())||i.item_id.toLowerCase().includes(filter.toLowerCase())).map(i=><article className="stock-card" key={i.item_id}><div className="stock-head"><div><strong>{i.title}</strong><small>{i.item_id} · Atualizado {date(i.synced_at)}</small></div><span className={"pill "+(!i.archived&&i.days!==null&&i.days<=((i.setting?.lead_days??3)+(i.setting?.safety_days??2))?"warn":"")}>{i.archived?"Histórico · fora de venda":i.status==="paused"?"Anúncio pausado":i.days===null?"Giro insuficiente":i.days<=(i.setting?.lead_days??3)+(i.setting?.safety_days??2)?"Risco de ruptura":"Em acompanhamento"}</span></div><div className="stock-numbers"><div><small>Saldo ML</small><b>{i.available}</b></div><div><small>Vendas hoje</small><b>{i.stats.today}</b></div><div><small>Vendas acumuladas no ML</small><b>{i.sold_quantity!=null?i.sold_quantity+" un.":(i.recorded_units??i.stats.all)+" un. (pedidos registrados)"}</b></div><div><small>Giro por dia</small><b>{i.daily.toFixed(1).replace(".",",")}</b></div><div><small>Comprar hoje</small><b>{i.qty}</b></div></div><div className="stock-foot"><span>Investimento: <b>{i.investment===null?"Cadastre o custo":money(i.investment)}</b></span>{!i.archived&&<button onClick={()=>openEdit(i.item_id)}>Conferência e reposição</button>}</div>{i.setting?.physical_count!=null&&<p className="stock-note"><AlertTriangle size={15}/> Contagem física: {i.setting.physical_count} un. ({date(i.setting.physical_counted_at||"")}). Compare com o saldo do ML e os pedidos reservados.</p>}</article>)}{!stockRows.length&&<div className="empty">Estoque ainda não sincronizado</div>}</section>}
