 <div className="promo-price">{needsPrice?<label>Preço<input inputMode="decimal" value={d.price||String(p.suggested_price??p.max_price??"")} onChange={ev=>setPromoDraft(x=>({...x,[key]:{...d,price:ev.target.value,confirm:false}}))}/></label>:<span>{money(price)}</span>}{needsStock&&<label>Qtd.<input inputMode="numeric" placeholder={p.stock?.min?"mín. "+p.stock.min:""} value={d.stock} onChange={ev=>setPromoDraft(x=>({...x,[key]:{...d,stock:ev.target.value,confirm:false}}))}/></label>}</div>
